-- Toolbox: changelog.lua
-- GENERATED by tools/build.py from CHANGELOG.md; edit CHANGELOG.md instead (make check
-- regenerates it; --check fails when it is stale). Shown by /toolbox version.
-- { kind, text }: kind is version / section / item / para, newest version first.

Toolbox.CHANGELOG = {
  { "version", "Unreleased" },
  { "section", "Added" },
  { "item", "Target HUD on its own strip can be mirrored too: name right-aligned, bars filling from the right, up to 5 icons to the left, at a fixed width so the bars don't move." },
  { "section", "Changed" },
  { "item", "Target HUD: one Mirrored checkbox (Toolbelt page, or /toolbox target mirror on|off) instead of a Target row choice: in the Toolbelt it puts the target left of your health bars, on its own strip it mirrors the strip. Target row is back to Above the buffs / Under everything. A saved \"Left of your bars\" becomes Mirrored on." },
  { "section", "Fixed" },
  { "item", "The target's mirrored place went back to \"Above the buffs\" after a reload." },
  { "version", "0.6.0 - 2026-09-29 (beta 7)" },
  { "section", "Added" },
  { "item", "Notifications for friends coming online (on, as a chat line) and guild members coming online (off by default), from the game's friend and guild events (Lua API 18). /toolbox notify friends|guild on|off." },
  { "item", "Skill levels gained and deaths: two new lines in the Today window (since midnight) and one in XP Detailed (this session). A level counts when a skill's trained level passes the highest it has been, so a scene's skill cap, or unlearning and relearning, doesn't count." },
  { "item", "Target HUD (/toolbox target on, or settings: Toolbelt, Target; off by default): your target's health and focus as bars and its effects as icons with the time left as a sweep, debuffs first, as the game's target frame shows it (\"health hidden\" for creatures that hide it). In the Toolbelt it has no text (the name and numbers are in the tooltip) and its bars are the same size as yours (the health bars' Size and Bar length). Where it goes (settings, Toolbelt, Target row, or /toolbox target place top|bottom|left): above the buffs (the default), under everything, or mirrored to the left of your health bars (its bars fill from the right, level with yours; up to 5 icons outward). With your health bars in the Toolbelt, above and under run across the whole Toolbelt: its bars start where yours do and its icons line up with your buffs. Above and on the left its space is kept with no target, so your bars and buffs don't jump when you pick one up; on the left that is a transparent blank area between the grip and your bars, labelled \"Target\" while settings are open. On its own strip it shows the name and percent. Creatures the game gives no display name (\"Entity with no name (Stag_04_Large(Clone))\") show a readable one (\"Stag Large\")." },
  { "item", "Toolbox can show at most 8 HUD strips at once (a game limit); a strip past that now says so in chat instead of failing." },
  { "item", "Notifications can also go to chat, and each can play a sound (a new rising chime, notify.ogg, replaceable like the alerts): the dropdown next to each in settings offers Window, HUD or Chat, each with or without \"+ sound\". /toolbox notify [<name>] via chat and /toolbox notify [<name>] sound on|off." },
  { "item", "The guild message of the day notification uses the game's own guild message getter and change event (Lua API 18) when the client has them: a new message shows at once. Older clients keep reading it from the social summary." },
  { "item", "If the game refuses to write Toolbox's saved settings to disk, Toolbox says so in chat (at most every 5 minutes) instead of failing silently." },
  { "item", "The Docs' Buff bar topic lists the cues that don't rely on colour (the debuff row, the blinking border, the alert sound, the seconds countdown, the sweep's size)." },
  { "version", "0.5.0 - 2026-09-29 (beta 6)" },
  { "section", "Changed" },
  { "item", "Needs a game client with Lua API 23 or newer (the live client's version); older clients skip Toolbox." },
  { "item", "The Toolbelt page in settings sets the whole thing up: Show the Toolbelt, and for the health bars, consumables bar and equipment bar one choice each: Off, Own strip or In Toolbelt (picking In Toolbelt switches the bar on, and the Toolbelt too). It's now the first page the settings window opens on." },
  { "item", "Health, focus and Vigor bars are thinner (half the text line, was 70%), so they read as separate bars with the strip no taller than before. /toolbox vitals debug also shows the size asked for next to the size laid out." },
  { "item", "Listed as \"Toolbox: Toolbelt, HUDs, Trackers and more.\", with a Support link to the project's page (github.com/shawnbutts/toolbox)." },
  { "item", "The settings window's category dropdown is called Settings (was Show), and Getting started in the Docs mentions the Toolbelt. The Consumables & gear page points to the Toolbelt page for adding its bars." },
  { "item", "The price site is called SotANET (or by its address, shroudoftheavatar.net) everywhere; the short name used before is a different domain." },
  { "item", "The settings shortcut is suggested as Ctrl+; (the game doesn't use Shift as a modifier, so the old Ctrl+Shift+; suggestion couldn't work; a Ctrl+Shift+; set in the add-on manager is recorded as Ctrl+;)." },
  { "section", "Fixed" },
  { "item", "\"Shroud.UI: this Row was destroyed\" after switching the consumables bar off (glued or not), and the same risk for every HUD strip after a rebuild (gluing, or a strip rebuilt after the game's element limit): a strip that is rebuilt or removed now lets go of its old elements at once." },
  { "section", "Added" },
  { "item", "Crafted counts what was made exactly on a game client with Lua API 24: each craft's result says what it made and how many (a craft of Crimson Pine Binding makes 4), counted as the craft finishes, not when you take it off the table. Leftovers such as an empty vial are listed apart, not as made. Older clients keep matching items taken off a station by name." },
  { "item", "Crafted and Gathered say when the game had more results than it could list (\"+3 results the game didn't list\"), so a total that's short is never shown as exact." },
  { "item", "A \"Test connection\" button under Estimated values (SotANET) in settings: looks up one item now, even with values off, and shows what happened under the button (and in chat), as /toolbox dd values test does." },
  { "item", "The name lists can be edited in settings: the buff bar's \"Always group by name\" (Buffs) and the consumables bar's \"Always on it\" and \"Left out\" names (Consumables & gear) each get a text box with Add and Remove, instead of only the chat commands." },
  { "item", "An empty buff bar (or Toolbelt) and consumables bar show their name while the settings window is open, so they can be found and placed before anything is on them." },
  { "item", "\"Show seconds left near the end\" (Buffs settings, or /toolbox buffs countdown on|off|<seconds>): whole seconds over the icon of a buff, debuff or consumable in its last 30 seconds (5-120). Off by default." },
  { "item", "Buff bar: \"Always group these kinds\" (Buffs settings, or /toolbox buffs group cat <Category> on|off) puts every buff of a category into the group slot, whatever its time left, e.g. Blessings." },
  { "item", "The Toolbelt: the buff bar with your health, focus and Vigor bars, consumables bar and equipment bar joined to it, one strip moved as one, now its own feature with its own settings category (which bars join it, only during combat, a summary of what's in it) and /toolbox toolbelt (vitals|consumables|gear on|off, combat on|off, move x y). The glue options moved there from HUD layout." },
  { "item", "Consumables bar, like the buff bar: long-lasting ones (the buff bar's \"Group buffs lasting longer than\") share one slot with a count, so seven Obsidian potions take one icon; \"Most icons\" caps the icons (the rest join that slot); and \"Only during combat\" on its own strip. /toolbox consumables max <n> and combat on|off." },
  { "item", "The consumables bar uses the game's buff categories (API 23): food, potions, weapon poisons and combat consumables (caltrops, bombs) by default, one checkbox per category in settings (or /toolbox consumables cat <Category> on|off). Names containing Scroll, Torch or Bait stay off it (/toolbox consumables exclude add|remove <name>). Older clients keep the name rules for food and potions. /toolbox buffs raw shows each buff's category; /toolbox api lists the new functions." },
  { "item", "Crafted and Gathered in Today Detailed: a Show dropdown switches between Looted, Crafted (items you took off crafting stations today, your crafts per recipe with exceptional and failed, and crafting XP; /toolbox crafted) and Gathered (what the nodes you harvested held, nodes, failed harvests and gathering XP; /toolbox gathered). Looted now leaves crafted and gathered items out; \"Include crafted and gathered items\" in settings (or /toolbox dd include on) puts them back. Crafted also lists the materials your crafts used (each recipe's ingredients times the crafts attempted; tools and optional ones left out), and, apart from what you made, anything else you took off a station (materials back, salvage returns). Needs a game client with Lua API 18." },
  { "item", "/toolbox api now also reports whether the game's craft and gather result events have fired (a line in chat the first time each does), with the fields of the first and last result and whether a crafted item's name matches the loot event's, to check them before the planned Crafted Today and Gathered Today windows are built on them. It also lists Vigor, and the docs' API 22." },
  { "version", "0.4.0 - 2026-09-29 (beta 5)" },
  { "para", "Fifth beta. Buff sweeps that keep pace with the game's own bar, a consumables bar for food and potions, an equipment bar with repair alerts, a Vigor bar, a reorganised settings window, lighter Docs and version windows, and performance fixes found by new stress tests." },
  { "section", "Added" },
  { "item", "Gear repair: an equipment bar (a HUD strip) shows worn items below a repair threshold (20% by default), each with a red sweep for the durability it has lost, lowest first; hover one for its durability. It hides when nothing needs repair, and shows every worn item while settings are open. Its icons follow the buff bar's icon size, and it can be glued to the buff bar as a third row under the debuffs (/toolbox gear glue on, or settings)." },
  { "item", "A \"Gear needs repair\" notification when an item drops below the threshold, and again when it breaks. Settings has an Equipment bar section; /toolbox gear lists worn items' durability." },
  { "item", "Consumables bar: food and Obsidian potions in effect on their own bar, with the buff bar's sweep, soonest to run out first, and off the buff bar. Flashes red with the buff alert when one is about to run out, then it goes. Can be glued to the buff bar as a row under the debuffs; /toolbox consumables add <name> tracks other buffs (e.g. a weapon poison, if it shows as a buff)." },
  { "item", "The XP and Today HUD strips are only built while their HUD form is chosen (Toolbox may have at most 8 HUD strips)." },
  { "item", "A gold Vigor bar under health and focus, with its percentage; hover it for what Vigor adds to health regen, focus regen and critical chance. It shows once you are past the level where Vigor applies (needs a game client with Lua API 20). /toolbox vitals vigor off or settings hides it." },
  { "section", "Changed" },
  { "item", "Settings window reorganised: a Show dropdown picks one category (XP & Today, Buffs, Consumables & gear, Health bars, Combat, Notifications, Sounds, HUD layout), built the first time it's picked, so opening settings creates far fewer elements (37 instead of about 240). It's wider (360 px). XP and Today each have one \"Hidden / Window / HUD strip\" choice instead of two checkboxes. Options that do nothing while their feature is off are greyed out. A new HUD layout category holds the glue options, every strip's position, and a summary of what shares a strip (and what falls back to its own when the buff bar is off). Alert sounds and volume have their own Sounds category." },
  { "item", "The Docs window (/toolbox help) shows one topic at a time, picked from a dropdown (each guide section, then Commands), each built the first time it's picked: it opens with 10 elements instead of about 70." },
  { "item", "The version window (/toolbox version) shows one version's changes at a time, picked from a dropdown (newest first), each built the first time it's picked: it opens with about 25 elements instead of the whole changelog's ~150." },
  { "item", "The store description and the project README list every current feature (they still described the add-on as it was two betas ago)." },
  { "item", "Health & focus bars: the bar length can now go down to 20 (was 100), for a compact strip." },
  { "section", "Fixed" },
  { "item", "Performance: once the settings window had been opened (the first-run welcome opens it), it kept updating its hidden labels every second (~9 UI calls a second). It now only does that while shown, and refreshes them as it opens. Also: the XP totals are read once a second instead of twice, the health & focus bars allocate nothing on a quiet tick, and HUD strips are only shown or hidden when that changes." },
  { "item", "Performance with a lot going on (found by new stress tests): the \"Gear needs repair\" notification re-read all your equipment on every notification check (every second for the first minute after login); it now uses the equipment bar's reading, and still notifies as soon as an item changes. Today Detailed redrew its whole list every second; now only when something on it changes (with a full day's 250 items it made ~8x less garbage). The buff bar makes less garbage per buff." },
  { "item", "Buff bar: a buff whose skill applies several effects could get its sweep's length from the wrong one, so the sweep sat out of step with the game's bar. The full length now comes from the effect whose time left matches, read the way the game reports it." },
  { "item", "Buff bar: the sweep no longer lags behind the game's. The game only draws a sweep picture's position when the picture is created, so our sweeps stayed where they first appeared (they lined up after a /lua reload, then fell behind; under half covered at the expiry alert). Each step now puts a new picture in place: at most 8 a second for all sweeps together, the one furthest behind first (turning red at the expiry alert goes straight away). The same for the equipment bar. It also shows the nearest step for the middle of the half second it stays up." },
  { "item", "\"Couldn't build the notify HUD: elements are being created too fast\" at login. A HUD strip that runs into the game's limit on how fast add-ons may create elements is now built again a moment later, without an error in chat (only the strips that failed are built again); and one part failing at start-up no longer stops the others." },
  { "version", "0.3.1 - 2026-09-28 (beta 4)" },
  { "para", "Fourth beta. Combat Detailed (damage by skill, the last minute as a chart, healing, targets, damage types and recent fights), an XP-over-the-last-hour chart in XP Detailed, a performance pass that leaves more room for other add-ons, and fixes for start-up errors." },
  { "section", "Changed" },
  { "item", "Performance: Toolbox asks much less of the game each second, leaving more room for other add-ons. With every window open, idle, it now makes about 4 UI updates a second instead of ~100 and a sixth of the garbage; in combat about a quarter of the UI updates and half the garbage. Windows only update what changed, Combat Detailed refreshes once a second, and the buff bar, combat HUD and XP chart reuse their data instead of rebuilding it." },
  { "section", "Added" },
  { "item", "XP Detailed: the last hour as a column chart under each track (2-minute columns of XP gained, gold for adventurer, green for producer), with the best rate per hour. It follows the \"Subtract XP lost\" setting." },
  { "item", "Combat Detailed: a window that pops up when you hover the combat HUD (or /toolbox combat detail). Damage by skill as bars, longest first, with hits, crits and over-time ticks on hover; the last minute as a column chart, damage done up and damage taken down; and healing with the share wasted as overheal. For this fight or the whole session. Uses the per-skill combat details of Lua API 17. Also: Targets (damage to each creature, same-named ones kept apart, and how long each took to kill) and Damage types (bars split by element for damage done and taken), and Recent fights: the last 10 fights as DPS bars, newest first, with damage, taken, healing, kills and top skill on hover." },
  { "item", "/toolbox combat events prints the next combat events' fields, to check what the game sends." },
  { "section", "Fixed" },
  { "item", "The XP HUD strip failed to load and its refresh then errored every second until the game turned Toolbox off. A strip that fails to build is now left empty instead of half-built, XP Detailed is built when first shown instead of at start-up (less to build at once), and the Docs and version windows share one window so Toolbox stays within the game's 8 windows per add-on." },
  { "item", "\"Elements are being created too fast\" errors at start-up with Combat Detailed pinned open: the charts use half as many elements, a pinned Combat Detailed opens a few seconds after start-up, and the first-run settings window opens a moment after the welcome." },
  { "item", "Combat events are now read whether the game hands them over as tables or as game objects (the buff list turned out to be game objects), so the combat HUD and the kill count can't silently miss them." },
  { "version", "0.3.0 - 2026-09-28 (beta 3)" },
  { "para", "Third beta. Notifications (guild message, mail, rewards, ...) in a window or on a HUD strip; the buff bar can replace the game's, groups long buffs, sorts by time left, flashes before a buff runs out, can show only in combat, and finally reads the game's full buff durations and debuffs; optional estimated item values from SotANET; alert sounds ship with the add-on (needs Lua API 15); XP keeps counting after XP is lost; and fixes for errors that could stop Toolbox." },
  { "section", "Added" },
  { "item", "Buff bar: a buff about to run out flashes a red border for its last seconds (the alert time, sound or not). \"Flash icons about to run out\" in settings, /toolbox buffs flash on|off." },
  { "item", "XP: \"Subtract XP lost (net change)\" in settings. Off (the default), XP figures count gains only; on, XP lost (for example on death) is subtracted from last hour, XP/hour, session and today's XP, which can then go negative." },
  { "item", "Notifications: a window tells you what's new since you last saw it: your guild's message of the day, new mail, mail about to expire, ransoms, new rewards and guild applications. It opens at login, after a reload, or as soon as something changes, with everything new together; nothing already seen shows again. Each can be switched on or off in settings (Notifications) or with /toolbox notify <name> on|off; /toolbox notify show shows everything current, /toolbox motd the guild message." },
  { "item", "Notification HUD: any notification can go to a HUD strip instead of the window (settings, or /toolbox notify <name> via hud). It lists the latest 20, newest on top, one line each; hover a line for the whole notice. It shows when something arrives and hides after 10 seconds (or a time you choose, or never), and stays while the pointer is on it. While the settings window is open it shows so you can place it, with a short note when it has nothing to list yet." },
  { "item", "Buff bar: buffs with more than 15 minutes left (Obsidian potions, for example) share one slot at the end of the row with a count; hover it to see each one and its time left. A buff moves back onto the bar once it has less than that left. The time is a setting (\"Group buffs lasting longer than\", or /toolbox buffs group after <minutes>|off). To always group a buff by name: /toolbox buffs group add <name>, remove <name>, reset." },
  { "item", "Buff bar: \"Replace the game's buff bar\" hides the game's own bar while Toolbox's is showing, and \"Click a buff to dismiss it\" works like the game's right-click Dismiss. Both off by default, and only on game clients with Lua API 16 (/toolbox buffs replace on|off, dismiss on|off)." },
  { "item", "Buff bar: buffs and debuffs are sorted by time left, the one that runs out soonest on the left. Buffs that never run out come next, and the long-lasting group stays at the right end." },
  { "item", "Buff bar: \"Only during combat\" shows the bar only while you're in combat (and 5 seconds after), so it can sit in your line of sight without being in the way. It also shows while the settings window is open, so you can place it. /toolbox buffs combat on|off. Alerts work either way. When the health & focus bars are glued to the buff bar, they hide and show with it." },
  { "item", "Today Detailed: optional estimated values. Each item shows its count times its 90-day average sale price from SotANET's public price list (player-uploaded receipts), and the header a total for the day; hover a value for the price each. Items with no recent sales stay blank. Off by default: switch on \"Estimated values (SotANET)\" in settings (or /toolbox dd values on) and Internet for Toolbox in the add-on manager. Only item names are sent; each price is kept for 24 hours, across reloads and restarts (/toolbox dd values refresh looks them up again). /toolbox dd values test [item] checks the connection with one lookup and prints the answer." },
  { "item", "/toolbox api lists which newer game functions this client has (buff bar, crafting, friends and guild), to check the client against the docs." },
  { "section", "Changed" },
  { "item", "Buff bar: the long-lasting slot's count has a dark outline, so it reads on light icons too." },
  { "item", "New debuff sound: a little longer (0.8 s), starting high and falling, so it carries in a fight." },
  { "item", "The alert sounds now come with the add-on (game clients at Lua API 15 or newer allow sounds in add-on packages), so there's nothing to copy by hand. Toolbox now needs Lua API 15. Your own sounds in the Lua folder (toolbox_buff_expiring.ogg, toolbox_debuff_landed.ogg) still win." },
  { "item", "/toolbox sounds debug is simpler; /toolbox sounds try is gone (sounds work in current clients)." },
  { "section", "Fixed" },
  { "item", "Buff bar: after a buff ran out while flashing red, the next buff to take its place kept the red shading. A slot is now cleared whenever a different buff moves into it." },
  { "item", "XP: after losing XP (for example on death), \"last hour\", XP/hour and today's XP stopped counting, on both adventurer and producer, until the total climbed back past its old high. A drop that holds for a few seconds is now accepted (and counted as no gain), and the two tracks are counted separately. /toolbox xp debug shows the numbers." },
  { "item", "Buff bar: debuffs weren't recognised (no debuff sound, no red row), and buff icons and full durations from the game's buff list were never read. The game hands add-ons its buff list as game objects rather than the documented plain tables, which Toolbox skipped; it now reads them." },
  { "item", "The debuff sound didn't play in game. The alert no longer depends only on the game's buff-change callback: the buff bar's own check notices a new debuff too. /toolbox buffs debug shows how many changes each one saw." },
  { "item", "Buff bar: a buff with two effects running (e.g. refreshed) shows the tooltip of the one that lasts longer. Buff names in the long-lasting list and in /toolbox buffs debug use only the first line of a long description, so a debug line is no longer cut short." },
  { "item", "Toolbox stopped with \"pattern too complex\" errors (and was disabled) when a buff had a very long description; the game's Lua gives up on a text pattern that standard Lua handles. The same could have happened with a long guild message. All such text is now trimmed without patterns." },
  { "item", "Buff bar: the sweep no longer lags the game's own buff bar. Buffs that load in after you log in (or zone) were taken for fresh casts, so their time left at that moment was remembered as their full length. Buffs that appear in the first 15 seconds after logging in, zoning or switching characters, or several at once, now count as already running. Lengths learned the old way are forgotten once; cast a buff again to teach it." },
  { "item", "Combat stats HUD: no more lines between the rows of the Dark background. It is now one flat black panel at the chosen opacity instead of the theme's panel look, whose shaded edges showed at every row." },
  { "version", "0.2.1 - 2026-09-27 (beta 2)" },
  { "para", "Second beta: the XP and Today windows can be HUD strips, /tbx version opens a changelog window, and fixes for the combat stats padding and the Docs command colours. Only the .ogg alert sounds ship now." },
  { "section", "Added" },
  { "item", "/tbx version also opens a version window: the same version line as in chat, then this changelog (newest first). tools/build.py bakes CHANGELOG.md into toolbox/changelog.lua, since the add-on can't read files; --check fails when it is out of date." },
  { "item", "The XP and Today windows can show as HUD strips instead (/tbx xp hud, /tbx daily hud, or \"As a HUD strip\" in settings): no title bar or frame, on the theme's dark panel, moved by the grip or /tbx xp move <x> <y>; the hover pop-ups work as over the windows. window switches back." },
  { "section", "Changed" },
  { "item", "Only the .ogg alert sounds are shipped (beta zip, tools/install.py); the add-on no longer looks for a default .wav. A player's replacement (Lua/toolbox_<name>.wav) or custom path still can be one." },
  { "section", "Fixed" },
  { "item", "Docs: the command list is in the same text colour as the rest (it was dimmer than its first line)." },
  { "item", "Combat stats HUD: the values now have the same padding on the right as the names on the left." },
  { "version", "0.2.0 - 2026-09-27 (beta 1)" },
  { "para", "First beta for hand-installing testers (make beta; see BETA.md). Highlights since 0.1.0: the XP and XP Detailed windows with a hover pop-up, Today and Today Detailed (items gained), a buff bar with clock sweeps and expiry / debuff alerts, health & focus bars (with glue to the buff bar), a combat stats HUD, a settings window with Docs, a first-run welcome, and a settings shortcut key. Full detail below." },
  { "section", "Added" },
  { "item", "A shortcut key for the settings window (Shroud.Keybind), suggested as Ctrl+; (Shift can't be a modifier, so the requested Ctrl+Shift+; isn't possible). Players change it in the add-on manager under Keys. The settings window and /toolbox key show the current key and whether the game or another binding has it; if the game refuses the suggested key, the binding is added without one." },
  { "item", "Docs window (/toolbox docs, or the Docs button that replaces \"Chat commands\" in settings): getting started, a short guide to each feature and its options, tips (moving HUD strips, the Lock Status Movement setting, adding combat stats on the fly, sounds), and every command, listed from the command registry so it stays current. The first-run welcome points to it." },
  { "item", "/toolbox version: version, build (the git commit, stamped into dist/ by tools/build.py, with + for uncommitted changes), API version, and how many copies of Toolbox are loaded (a second copy left in the Lua folder would share and tangle the global Toolbox table)." },
  { "item", "Documentation for adding combat HUD stats on the fly: /toolbox combat help (every combat option, with the find / add / remove steps and examples), a clearer /toolbox combat stats, a visible hint in settings, and a step-by-step section in the store readme." },
  { "item", "Combat stats background: a Dark (theme inset) or Light (theme @text) panel behind the whole strip, or None, with its own opacity (default Dark at 70%) that doesn't fade the text (/toolbox combat bg, settings). Row names use normal text instead of dim, values bright." },
  { "item", "Combat stats HUD (/toolbox combat): fight timer, DPS (last 5 s and fight average, pet optional), damage taken and healing per second, crit % and avoided % from your combat chat lines, plus character stats you choose (MagicResistance by default; /toolbox combat stat add <Name>). Own Size and position; reset from chat or settings." },
  { "item", "Glue the health & focus bars to the buff bar (/toolbox vitals glue on or the settings checkbox): one HUD strip with health & focus on the left and buffs on the right, one grip and one remembered position, sized to what's showing. Unglued positions are kept for switching back." },
  { "item", "Health & focus bars flash when low: below a threshold (default 20%, /toolbox vitals flash <n> or the settings slider; can be turned off) the bar and its number swap to the theme's bright text colour every 0.4 s. A Test flash button (and /toolbox vitals flash test) flashes both bars for 5 s to preview it." },
  { "item", "Health & focus bars: show or hide the bars and the numbers separately (not both), and a None / Dark / Light background behind the numbers from the UI theme (inset / card classes). Settings has checkboxes and a dropdown; /toolbox vitals text|bars on|off and /toolbox vitals bg none|dark|light." },
  { "item", "Health & focus bars: a Size setting (75-250%, /toolbox vitals size <n> and a slider) that scales the text, bars, gap and strip together. The numbers now sit just after the bars (left-aligned, small gap) in a fixed-width box so both bars line up. The strip has its own size and no longer follows the global text size." },
  { "item", "Health & focus bars (/toolbox vitals): a movable HUD strip with health (red) and focus (blue) bars and \"current / max\", with width and position settings. Maximums come from the Health / Focus stats found with /toolbox stats; vigor isn't exposed to add-ons." },
  { "item", "/toolbox stats [word]: lists character stats matching a word (index, internal and displayed name, value) and how many matching ones are hidden from add-ons. For finding the stats behind own health / focus / vigor bars, which the docs don't name." },
  { "item", "Buff bar position controls: 10 px nudge buttons, Reset and a position readout in settings, and /toolbox buffs move <x> <y>. (Its drag grip is hidden while the game's HUD is locked.) The position is also remembered by the add-on, in case the game's own memory doesn't survive a reload." },
  { "item", "Buff bar (/toolbox buffs): buffs and debuffs as their skill icons on a HUD strip, debuffs outlined in red, with a clock-style sweep over each icon (toolbox/clock.png) instead of a countdown. Built from a fixed pool of slots." },
  { "item", "Alerts: a sound when a buff is about to run out (/toolbox buffalert <1-60>, default 10 s, fires once as the threshold is crossed) and when a new debuff lands (/toolbox debuffalert). Sounds are found at a custom path, then Lua/toolbox_<name>.ogg, then the package; missing files are silent. /toolbox sounds reports them and sets the volume. All in settings, with Test buttons." },
  { "item", "tools/install.py copies the alert sounds to Lua/toolbox_<name>.ogg (and .wav copies, when generated, to try as a custom path)." },
  { "item", "The sweep now shows a buff's real progress when it was already running as the add-on started or reloaded (it used to treat every such buff as brand new). The full duration comes from the game's TotalDuration/CurrentDuration when they agree with the time remaining, otherwise from the add-on's own record kept across /lua reload. /toolbox buffs debug lists the timing data." },
  { "item", "Buff sweeps were wrong for buffs already running when the add-on started (a Light spell half used showed 13%): the game's TotalDuration/CurrentDuration are empty, so the first time left seen was taken as the full duration. Durations are now learned from casts seen while the add-on runs (saved per character as buff_durations); a buff with no known duration shows no sweep until it is cast again. Old saved reload timers (which could hold such wrong totals) are ignored, and a buff that briefly vanishes during a scene load keeps its timer." },
  { "item", "Buff timers count down on the add-on's own clock and follow the game's time remaining only when that value actually changes (a value jumping up is a recast). In game the sweep stalled and then jumped, which is what a value refreshed only now and then produces; the expiry alert was late for the same reason. /toolbox buffs trace [name] logs the game's raw values for 10 s, for the buffs whose rune or displayed name contains name (up to 8 without one); debug and trace show both names." },
  { "item", "The sweep has 120 steps (3 degrees each) instead of 24: with 24, a long buff such as a 20-minute Light spell moved only every 50 s and looked frozen. clock.png is now 960 x 576 (48 px frames, 88 KiB)." },
  { "item", "The sweep turns red the moment a buff's expiry alert fires (a second, red set of frames in clock.png); a recast turns it back. The normal sweep is darker (82% instead of 62%)." },
  { "item", "Sound Test buttons and /toolbox sounds test report the clip, channel and volume, then check whether the game is actually playing it, which tells a file that didn't decode apart from a volume problem." },
  { "item", "Alert sounds, generated by art/alerts.py: \"buff about to run out\" (art/buff_expiring.ogg, two soft falling chimes) and \"enemy debuff landed\" (art/debuff_landed.ogg, two quick hollow notes drooping down a minor triad over a low thump). Not in the package yet: the published packaging rules don't allow audio files, so they move into toolbox/ once they do." },
  { "item", "Store icon: a carpenter's tool tote on a leather tile with a bronze frame (toolbox/icon.png, source in art/icon.svg)." },
  { "item", "Today Detailed window (/toolbox dailydetailed, alias dd; pops up when hovering Today): the day's gold and kills plus every item gained today with its count. Settings has checkboxes to show it and to turn its hover pop-up off." },
  { "item", "Daily stats window (/toolbox daily, also in settings): gold picked up, kills by you or your pet, and adventurer / producer XP gained today. Resets at local midnight (midnight UTC if the local clock is unavailable); kept per character across reloads and relogs." },
  { "item", "Line spacing setting (/toolbox spacing <0-12> and a slider in settings). Text lines now have a fixed height that follows the text size, so smaller text makes the windows shorter." },
  { "item", "Hovering the compact XP window pops up the Session XP window after a short delay; it stays while the pointer is over either window. Can be turned off in settings." },
  { "item", "Compact XP window (/toolbox compact, also in settings): session time, current adventurer and producer pools, and XP earned on each in the last hour." },
  { "item", "/toolbox config opens a Toolbox Settings window: a text-size slider for the Session XP window and a checkbox to show or hide it." },
  { "item", "/toolbox font <9-32> sets the Session XP window's text size (saved per character)." },
  { "section", "Fixed" },
  { "item", "The settings shortcut suggested Ctrl+; (\"Ctrl+Semicolon\"), which showed as bound but never reached the add-on (0 presses), while a player-set Ctrl+Shift+; works despite the docs saying Shift is never a modifier. The suggestion is now Ctrl+Shift+; as first asked, then Ctrl+;, then none." },
  { "item", "In game no alert sound loaded from any path (all timed out). The sound docs say paths are relative to \"the addon's Lua folder\", which for a package may be Lua/toolbox/: each alert now also tries .ogg and .wav inside the package folder, tools/install.py copies them there for local testing (not part of the store package), the per-path wait is 2 s, and /toolbox sounds debug lists each path tried with what ShroudLoadSound answered." },
  { "item", "Alert sounds claimed \"ready\" while the game's sound list was empty, with a table (the same one for both) as their clip. A bare local found in the load loop apparently kept an old value in the game's Lua (MoonSharp), where standard Lua resets it to nil. Every local now starts with an explicit = nil (tools/build.py refuses bare declarations), and only a real clip name counts." },
  { "item", "The empty list also means the .ogg files never decoded in game. Each alert now tries Lua/toolbox_<name>.wav right after the .ogg; tools/install.py copies the .wav versions." },
  { "item", "Alert sounds never played in game: ShroudListSound() entries came back as tables, not the documented name strings, so the add-on recorded a table as the clip (the same one for both sounds) and could never find it again. Clip names are now read from strings, from a table's name field, or from a list wrapped in one more table; /toolbox sounds debug shows what the game returns, one level deep." },
  { "item", "Sound Test reported \"the game's sound list was cleared\" in game: the clip recorded at load time wasn't found by its exact name at play time. Playing now also matches any clip whose name contains the file's base name (as loading does). /toolbox sounds debug prints the game's raw sound list and what each alert recorded." },
  { "item", "The combat stats strip failed to build in game (\"style color takes a number or a string\"): a label style's colour could be nil, and the game's Lua (MoonSharp) passes a nil table entry on to the UI, unlike standard Lua. Labels now always get a theme colour. The same kind of nil was removed from buff icon textures, window positions and a Today row's tooltip, and the build now refuses table entries that end in \"or nil\"." },
  { "item", "A HUD strip that fails to build no longer stops the others from building and showing; the error is reported in chat. /toolbox combat debug describes the combat strip (shown setting, build error, strip visibility, size, position). The combat rows no longer repeat an element id." },
  { "item", "The combat stats strip disappeared once it got a background: its rows were laid over the panel with a margin of minus the strip's width, but the game clamps margins to -64..256, so the rows were pushed out of the strip. The panel is now per-row slabs one line tall, with each row pulled up by its line height (well inside the limit). The test harness now clamps margins and paddings like the game." },
  { "item", "The buff bar couldn't be dragged past about two-thirds of the screen: its strip was always 20 icon slots wide (invisible when empty), and the game keeps HUD frames on screen. The strip is now sized to the icons showing (one row without debuffs) and re-fits as buffs come and go." },
  { "item", "The Light number background showed nothing in game (the theme's card class draws no panel behind a label). Light is now a panel in the theme colour @text with dark numbers, on a wrapper so switching back to Dark still shows the inset panel." },
  { "item", "The drag grip at a HUD strip's top-left corner covered the first number (health & focus bars) or icon (buff bar): both strips now keep ~14 px free for it (Toolbox.Window.GRIP)." },
  { "item", "Health & focus bars showed \"--\" and stayed empty in game: when the per-frame current value isn't a number they now read the CurrentHealth / CurrentFocus stats. /toolbox vitals debug shows each source." },
  { "item", "README: the \"Development\" heading had been dropped when the Buff bar section was added." },
  { "item", "Line spacing had no visible effect: label heights are now pinned with minHeight/maxHeight as well as height, so a theme class's minimum height can't override them. /toolbox spacing with no number now measures the laid-out line height." },
  { "item", "The \"Show daily stats window\" checkbox in settings now follows /toolbox daily and the window's close button (it only worked in one direction)." },
  { "section", "Changed" },
  { "item", "The first run also opens the settings window, after the welcome line (/toolbox welcome does both)." },
  { "item", "/toolbox help opens the Docs window; the chat list of commands moved to /toolbox commands." },
  { "item", "/toolbox (or /tbx) with no argument opens the settings window instead of printing help; a one-time welcome line on first run says so, and the settings window opens with a short intro and a \"Chat commands\" button." },
  { "item", "Alert sounds: the defaults live in the add-on's folder (Lua/toolbox/<name>.ogg/.wav); a replacement in the Lua folder beside it (Lua/toolbox_<name>) wins. The package-relative guesses are gone (paths are Lua-root relative), and tools/install.py no longer writes to the Lua folder." },
  { "item", "HUD strips are owned by hud.lua (Toolbox.Hud): the buff bar and the health & focus bars build only their content, and the HUD puts it in one strip each or a shared glued strip, sizes it and remembers its position." },
  { "item", "HUD position controls (settings rows and the move command) are shared by the buff bar and the health & focus bars (Toolbox.Window.HudMover, Toolbox.Config.PositionRows, Toolbox.MoveCommand)." },
  { "item", "The hover pop-up logic is shared (hover.lua) between XP / XP Detailed and Today / Today Detailed." },
  { "item", "Window names and commands: the compact window is now XP (/toolbox xp), and the old Session XP window is XP Detailed (/toolbox xpdetailed, alias xpd). /toolbox compact is gone. Window positions and settings carry over." },
  { "item", "The build allows os.date / os.time (for the daily reset); other os and all io use is still refused." },
  { "item", "Lower minimum window heights (Session XP 60, compact 50) now that lines can be tighter." },
  { "item", "\"Next level\" and \"Last hour\" lines use the normal text colour instead of the dimmed one." },
  { "item", "Sample history now covers the last hour (was 10 minutes); the session is stored in saved vars once per tick instead of on every XP event." },
  { "item", "More compact Session XP window: level and % share the track heading, gains and rates share one line, and elapsed time sits beside Reset. Smaller default text (12), a smaller default size, and a lower minimum size (160x100). Content scrolls when the window is made smaller." },
  { "item", "The \"Next level\" line always shows the XP still needed, and says why there is no time estimate (\"no XP gained yet\", \"max level\") instead of a bare --." },
  { "item", "10px left/right gutter in the Session XP window so the progress bars no longer touch the edge." },
  { "version", "0.1.0 - 2026-09-27" },
  { "section", "Added" },
  { "item", "/toolbox and /tbx slash commands with help, xp and reset." },
  { "item", "Session XP tracking for adventurer and producer XP from the total XP values: elapsed time, XP gained, XP/hour for the session and the last 10 minutes, level, % through the level and estimated time to the next level." },
  { "item", "\"Session XP\" window (Shroud.UI) with a Reset button; remembers whether it is open and where it is." },
  { "item", "Sessions survive /lua reload; a new login starts a new session." },
}
